using System;using System.IO;using System.Linq;using System.Text;using System.Drawing;using System.Threading;using System.Collections.Generic;using System.Windows.Forms;
namespace GearLab {
 public static class Settings63Tests {
  static IEnumerable<Control> All(Control c){yield return c;foreach(Control child in c.Controls)foreach(var next in All(child))yield return next;}
  public static int Run(string folder){folder=Path.GetFullPath(folder);Directory.CreateDirectory(folder);Environment.SetEnvironmentVariable("GEARLAB_PROFILE_DIR",Path.Combine(folder,"profile"));int checks=0;var report=new StringBuilder();Action<bool,string> check=(ok,label)=>{if(!ok)throw new Exception(label);checks++;report.AppendLine("PASS "+label);};Action<Func<bool>> wait=ready=>{var clock=System.Diagnostics.Stopwatch.StartNew();while(!ready()&&clock.Elapsed.TotalSeconds<90){Application.DoEvents();Thread.Sleep(15);}if(!ready())throw new Exception("3D timeout");};try{
   check(AppSettings.Folder==Path.Combine(folder,"profile"),"isolated preferences profile");var defaults=new AppSettings();check(defaults.Theme==GearTheme.Тёмная,"Blender dark default");var draft=defaults.Clone();draft.Language=GearLanguage.English;draft.Colors["Panel"]="#334455";draft.AnimationScale=.37;AppSettings.Commit(draft);draft.Colors["Panel"]="#112233";draft.AnimationScale=9;check(AppSettings.Current.AnimationScale==.37&&AppSettings.Current.Colors["Panel"]=="#334455","applied preferences independent of editor draft");var loaded=AppSettings.LoadFrom(AppSettings.SettingsPath);check(loaded.Language==GearLanguage.English&&loaded.AnimationScale==.37&&loaded.Colors["Panel"]=="#334455","language palette and animation survive reload");draft=loaded.Clone();draft.Colors["Panel"]="invalid";bool rejected=false;try{draft.Validate();}catch{rejected=true;}check(rejected,"invalid hex rejected");draft=loaded.Clone();draft.AnimationScale=double.NaN;rejected=false;try{draft.Validate();}catch{rejected=true;}check(rejected,"nonfinite speed rejected");
   File.WriteAllText(Path.Combine(folder,"broken.json"),"{broken");check(AppSettings.LoadFrom(Path.Combine(folder,"broken.json")).Theme==GearTheme.Тёмная&&!string.IsNullOrEmpty(AppSettings.LoadWarning),"corrupt preferences recovered with diagnostic");
   using(var form=new Form()){var combo=new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList};combo.Items.AddRange(new[]{"Изометрия","Сверху"});combo.SelectedIndex=1;var field=new TextBox{Text="Мой проект 123"};var label=new Label{Text="Настройки"};form.Controls.AddRange(new Control[]{combo,field,label});AppSettings.Apply(form);check(label.Text=="Preferences","English control label");check((string)combo.SelectedItem=="Сверху","combo internal camera token unchanged");check(field.Text=="Мой проект 123","editable project names preserved");var late=new Button{Text="Рассчитать"};form.Controls.Add(late);check(late.Text=="Calculate"&&late.BackColor==UiPalette.Get("Field"),"new controls inherit language and palette");draft=AppSettings.Current.Clone();draft.Language=GearLanguage.Русский;AppSettings.Commit(draft);AppSettings.Apply(form);check(label.Text=="Настройки"&&late.Text=="Рассчитать","live switch back to Russian");label.Text="Сохранено: sample.gear.json";check(label.Text=="Сохранено: sample.gear.json","dynamic Russian status");draft.Language=GearLanguage.English;AppSettings.Commit(draft);AppSettings.Apply(form);check(label.Text=="Saved: sample.gear.json","dynamic status localized after switch");label.Text+=" · Настройки";draft.Language=GearLanguage.Русский;AppSettings.Commit(draft);AppSettings.Apply(form);check(label.Text=="Сохранено: sample.gear.json · Настройки","appended translated status restores complete Russian source");draft.Language=GearLanguage.English;AppSettings.Commit(draft);var joint=new RobotJoint{Name="Моё звено"};var pg=new PropertyGrid{SelectedObject=joint};form.Controls.Add(pg);var property=System.ComponentModel.TypeDescriptor.GetProperties(joint)["MotorTorque"];check(property.DisplayName=="Torque at operating speed, N·m"&&ReferenceEquals(pg.SelectedObject,joint),"localized property metadata retains original project object");}
   draft=AppSettings.Current.Clone();draft.Colors.Clear();AppSettings.Commit(draft);
   for(int kind=0;kind<13;kind++){var p=Engine.Starter(kind);string before=ReleaseSupport.Serialize(p);var ru=AppSettings.Current.Clone();ru.Language=GearLanguage.Русский;AppSettings.Current=ru;var a=Engine.Calculate(p);ru.Language=GearLanguage.English;var b=Engine.Calculate(p);check(a.Valid==b.Valid&&a.Actual==b.Actual&&before==ReleaseSupport.Serialize(p),"language preserves reducer parameters and ratio "+kind);}
   using(var reducers=new ReducerWorkspaceForm())using(var shell=new WorkspaceShell(reducers)){shell.Show();wait(()=>reducers.MainView!=null);reducers.SelectWave();reducers.MainView.ShowFullModel();wait(()=>reducers.MainView.SceneReady);var original=ReleaseSupport.Serialize(reducers.MainView.CurrentParameters);shell.Navigate("settings");var settings=(SettingsForm)shell.Pages.SelectedTab.Tag;settings.Draft.Language=GearLanguage.English;settings.Draft.Colors["Viewport"]="#273849";check(settings.ApplyDraft(),"settings page Apply");using(var preview=new Bitmap(shell.Width,shell.Height)){shell.DrawToBitmap(preview,new Rectangle(Point.Empty,preview.Size));preview.Save(Path.Combine(folder,"preferences-en.png"));}settings.Draft.AnimationScale=8;check(AppSettings.Current.AnimationScale!=8,"later draft edits cannot leak through Apply");All(settings).OfType<Button>().Single(b=>b.Text=="Cancel").PerformClick();check(settings.Draft.AnimationScale==AppSettings.Current.AnimationScale,"Cancel restores draft after Apply");shell.Navigate("reducer");check(original==ReleaseSupport.Serialize(reducers.MainView.CurrentParameters),"settings preserve open reducer geometry parameters");using(var bitmap=new Bitmap(shell.Width,shell.Height)){shell.DrawToBitmap(bitmap,new Rectangle(Point.Empty,bitmap.Size));bitmap.Save(Path.Combine(folder,"workspace-en.png"));}File.WriteAllLines(Path.Combine(folder,"visible-en.txt"),All(shell).Where(c=>c.Visible&&!(c is TextBoxBase)&&!(c is NumericUpDown)).Select(c=>c.GetType().Name+": "+c.Text).ToArray(),Encoding.UTF8);
    shell.Navigate("train");Application.DoEvents();check(All(shell.Pages.SelectedTab).OfType<Button>().Any(b=>b.Text=="New train"),"new train page localized");using(var preview=new Bitmap(shell.Width,shell.Height)){shell.DrawToBitmap(preview,new Rectangle(Point.Empty,preview.Size));preview.Save(Path.Combine(folder,"train-en.png"));}shell.Navigate("settings");settings.Draft.Language=GearLanguage.Русский;check(settings.ApplyDraft(),"switch complete workspace to Russian");shell.ApproveTestClose();shell.Close();}
   using(var scene=new WpfScene()){var r=Engine.Calculate(Engine.Starter(1));r.Model=CadBuilder.Build(r);scene.SetResult(r,false);int initial=scene.TriangleCount;var changed=AppSettings.Current.Clone();changed.Quality=GearQuality.Подробный;AppSettings.Commit(changed);wait(()=>scene.Ready);check(scene.TriangleCount>initial,"quality setting rebuilds existing preview mesh");check(((System.Windows.Media.SolidColorBrush)scene.Root.Background).Color==UiPalette.Wpf("Viewport"),"3D viewport custom background");scene.SavePng(Path.Combine(folder,"scene-custom.png"),1000,700);}
   File.WriteAllText(Path.Combine(folder,"settings63-results.txt"),report+"PASS "+checks+" assertions",Encoding.UTF8);return 0;
  }catch(Exception ex){File.WriteAllText(Path.Combine(folder,"settings63-error.txt"),report+ex.ToString(),Encoding.UTF8);return 1;}}
 }
}
